-- Better Auth's rate-limit counters (src/auth.ts, `rateLimit.storage: "database"`): one row per client IP and path,
-- shared by every isolate. Generated by Better Auth (`getMigrations`), plus an index for its pruning of old rows.

create table "rateLimit" ("id" text not null primary key, "key" text not null unique, "count" integer not null, "lastRequest" bigint not null);
create index "rateLimit_lastRequest_idx" on "rateLimit" ("lastRequest");
